import{_ as a,o as r,c as o,a2 as e}from"./chunks/framework.CXsxtpvq.js";const s="/asset-studio/shots/07-library-character.webp",d="/asset-studio/shots/08-library-outfit-set.webp",b=JSON.parse('{"title":"프롬프트 라이브러리","description":"","frontmatter":{},"headers":[],"relativePath":"ko/guide/library.md","filePath":"ko/guide/library.md"}'),n={name:"ko/guide/library.md"};function i(l,t,h,c,p,g){return r(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="프롬프트-라이브러리" tabindex="-1">프롬프트 라이브러리 <a class="header-anchor" href="#프롬프트-라이브러리" aria-label="Permalink to &quot;프롬프트 라이브러리&quot;">​</a></h1><p><strong>프롬프트 수정</strong> 메뉴는 프롬프트를 다시 쓸 수 있는 조각으로 관리합니다. 생성할 때는 고른 조각들이 정해진 순서로 이어져 하나의 프롬프트가 됩니다.</p><h2 id="작품-›-캐릭터-›-의상" tabindex="-1">작품 › 캐릭터 › 의상 <a class="header-anchor" href="#작품-›-캐릭터-›-의상" aria-label="Permalink to &quot;작품 › 캐릭터 › 의상&quot;">​</a></h2><p>모든 것은 <strong>작품</strong> 아래에 있습니다. 캐릭터 코드(C001 등)는 작품마다 따로 매기므로, 작품이 다르면 같은 코드라도 다른 캐릭터입니다.</p><ul><li><strong>+ 작품</strong>: 작품을 만듭니다. 작품 공통 프롬프트(예: <code>fantasy</code>)를 넣을 수 있습니다.</li><li><strong>+ 캐릭터</strong>: 캐릭터의 외형 프롬프트를 적습니다. 머리색, 눈색, 체형처럼 의상과 상관없이 늘 같은 것만 넣습니다.</li></ul><p><img src="'+s+'" alt="캐릭터 외형 편집"></p><p>프롬프트 입력란은 한 줄에 태그 하나 또는 문장 하나를 적습니다. 쉼표로 이은 태그를 붙여 넣어도 되고, <strong>줄 정리</strong>를 누르면 한 줄에 하나씩 나눠 줍니다. 입력하는 동안 Danbooru 태그 자동완성이 나옵니다(설정에서 끌 수 있음).</p><h2 id="조각의-종류" tabindex="-1">조각의 종류 <a class="header-anchor" href="#조각의-종류" aria-label="Permalink to &quot;조각의 종류&quot;">​</a></h2><table tabindex="0"><thead><tr><th>분류</th><th>예</th><th>설명</th></tr></thead><tbody><tr><td>의상</td><td>상의, 하의, 신발, 손, 전체</td><td>부위별로 따로 만들고 의상 세트로 묶습니다.</td></tr><tr><td>감정·동작</td><td>웃음, 놀람, 생각 중</td><td>일반(SFW)과 성인(NSFW)으로 나뉩니다. 감정마다 기본 구도를 정할 수 있습니다.</td></tr><tr><td>구도</td><td>상반신, 전신</td><td>구도마다 &quot;넣을 의상 부위&quot;를 제안합니다(상반신이면 손·상의).</td></tr><tr><td>화풍</td><td>작가 태그</td><td>생성할 때 고릅니다.</td></tr><tr><td>공통</td><td>품질 태그(긍정), 제외 태그</td><td>모든 이미지에 붙일 태그입니다.</td></tr></tbody></table><h2 id="의상-세트" tabindex="-1">의상 세트 <a class="header-anchor" href="#의상-세트" aria-label="Permalink to &quot;의상 세트&quot;">​</a></h2><p><strong>+ 의상 세트</strong>는 부위별 의상 조각을 하나의 의상으로 묶습니다. 생성할 때 구도에 맞춰 필요한 부위만 들어가므로, 상반신 이미지에 신발 태그가 섞여 구도가 흐트러지는 일을 막습니다.</p><p><img src="'+d+'" alt="의상 세트: 부위별 조각"></p><h2 id="범위-전역-·-작품-공용-·-캐릭터" tabindex="-1">범위: 전역 · 작품 공용 · 캐릭터 <a class="header-anchor" href="#범위-전역-·-작품-공용-·-캐릭터" aria-label="Permalink to &quot;범위: 전역 · 작품 공용 · 캐릭터&quot;">​</a></h2><p>왼쪽 위의 범위 버튼으로 조각을 누가 쓸지 정합니다.</p><ul><li><strong>전역</strong>: 모든 작품에서 씁니다(예: 품질 태그).</li><li><strong>작품 공용</strong>: 그 작품의 모든 캐릭터가 씁니다(예: 샘플의 감정 다섯 가지).</li><li><strong>캐릭터</strong>: 그 캐릭터만 씁니다(예: Lyra의 교복).</li></ul><p>같은 코드의 조각이 여러 범위에 있으면 캐릭터 → 작품 공용 → 전역 순으로 가까운 것이 쓰입니다.</p><h2 id="모델-계열-표시" tabindex="-1">모델 계열 표시 <a class="header-anchor" href="#모델-계열-표시" aria-label="Permalink to &quot;모델 계열 표시&quot;">​</a></h2><p>조각마다 <strong>Anima</strong>, <strong>SDXL·IL</strong>, <strong>공용</strong> 표시가 있습니다. 작업 화면은 고른 모델 계열에 맞는 조각과 공용 조각만 보여 줍니다. Anima용으로 쓴 문장형 프롬프트가 SDXL에 섞이는 일을 막기 위한 것입니다.</p><h2 id="지우기와-휴지통" tabindex="-1">지우기와 휴지통 <a class="header-anchor" href="#지우기와-휴지통" aria-label="Permalink to &quot;지우기와 휴지통&quot;">​</a></h2><p>조각을 지우면 라이브러리 <strong>휴지통</strong>으로 갑니다. 휴지통에서 되살릴 수 있습니다.</p>',20)])])}const _=a(n,[["render",i]]);export{b as __pageData,_ as default};
